/* Leadwriting v19 Ein Kinoabend - leadwriting.de/testv1 - head (aus _live/build_testv1.py) */
document.write("<!-- Kalender: kein Preconnect beim Seitenaufruf (Gesamtpr\u00fcfung). 99-system setzt ihn erst nach Einwilligung (window.lwEinwilligung). -->\n<link rel=\"preload\" as=\"image\" href=\"https://onecdn.io/media/7fdb9cf7-563b-4c3d-ade1-2b529c0fad12/full\" fetchpriority=\"high\">\n<!-- Anton liegt lokal (kein Aufruf bei Google vor der Einwilligung) -->\n<link rel=\"preload\" as=\"font\" type=\"font/woff\" href=\"https://raw.githubusercontent.com/Marcofrnz/leadwriting-v1-assets/685be49c6f2634b54a2efbf78f194ce0e2c9c374/assets/v19/anton-regular.woff\" crossorigin>\n<style id=\"lw-basis\">\n/* Gemeinsame Grundlage aller 10 Hero-Varianten (Leadwriting CI \u201eMarmor bei Nacht\u201c).\n   Jede Variante bringt ihr eigenes CSS mit und darf hier alles \u00fcberschreiben. */\n\n@font-face{font-family:Sora;src:url(https://raw.githubusercontent.com/Marcofrnz/leadwriting-v1-assets/527d0805d1b211791a0302e4d1cbf88f9cfcb6f7/assets/fonts/c10/sora-variable.woff2) format(\"woff2\");font-weight:100 800;font-display:swap}\n@font-face{font-family:\"DM Sans\";src:url(https://raw.githubusercontent.com/Marcofrnz/leadwriting-v1-assets/527d0805d1b211791a0302e4d1cbf88f9cfcb6f7/assets/fonts/c10/dmsans-variable.woff2) format(\"woff2\");font-weight:100 1000;font-display:swap}\n\n:root{\n  --lw-deep:#091d2d; --lw-navy:#12324a; --lw-blue:#315a73; --lw-nav:#0a202d; --lw-floor:#142e40;\n  --lw-glow:#6a3336; --lw-glow2:#544451;\n  --lw-cloud:#edf0f2; --lw-card:#f1f3f5; --lw-mist:#e4ebed; --lw-ivory:#f8f4ee; --lw-stone:#efe9df; --lw-paper:#f4f3ed;\n  --lw-ink:#193340; --lw-text:#263e4e; --lw-body:#485864; --lw-line:#c4cacc;\n  --lw-rust:#8e4338; --lw-copper:#b66b55; --lw-copper-light:#d29a82; --lw-eyebrow-dark:#e6cbbb;\n  --lw-cream:#f5e9dd; --lw-cream2:#f8ede2; --lw-sand:#efddce; --lw-peach:#f1d2c2; --lw-rose:#e6b6ad; --lw-bubble:#f1e4d7;\n  --lw-label:#6c4336; --lw-body-dark:#e5dbd2;\n  --lw-gutter:clamp(16px,4.2vw,72px);\n  --lw-max:1320px;\n  --ease-out:cubic-bezier(.22,1,.36,1);\n}\n\n*,*::before,*::after{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;text-size-adjust:100%}\nbody{margin:0;background:var(--lw-cloud);color:var(--lw-ink);font-family:\"DM Sans\",system-ui,sans-serif;font-size:17px;line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:clip}\nimg,video,svg{display:block;max-width:100%}\na{color:inherit}\nbutton{font:inherit}\nh1,h2,h3{font-family:Sora,system-ui,sans-serif;font-weight:600;letter-spacing:-.045em;line-height:1.12;margin:0}\np{margin:0}\n\n/* Logo: PNG als Maske, Farbe \u00fcber currentColor */\n.lw-logo{display:block;width:62px;aspect-ratio:575/483;background:currentColor;\n  -webkit-mask:url(https://onecdn.io/media/1995fd7b-b3a0-443c-a922-90d3902e7a71/full) center/contain no-repeat;mask:url(https://onecdn.io/media/1995fd7b-b3a0-443c-a922-90d3902e7a71/full) center/contain no-repeat}\n\n/* Kopfleiste (Standard: transparent \u00fcber dem Hero) */\n.lw-nav{position:absolute;inset:0 0 auto;z-index:50;display:flex;align-items:center;justify-content:space-between;gap:24px;\n  padding:20px var(--lw-gutter);color:var(--lw-cream)}\n.lw-nav__links{display:flex;align-items:center;gap:28px;font-size:14px;font-weight:500}\n.lw-nav__links a{text-decoration:none;opacity:.92}\n.lw-nav__links a:hover{opacity:1;text-decoration:underline;text-underline-offset:4px}\n.lw-nav--light{color:var(--lw-navy)}\n@media (max-width:860px){.lw-nav__links a:not(.lw-btn){display:none}.lw-nav{padding-top:14px;padding-bottom:14px}.lw-logo{width:50px}}\n\n/* Buttons */\n.lw-btn{display:inline-flex;align-items:center;gap:12px;border-radius:8px;padding:15px 22px;font:600 15px/1.2 \"DM Sans\",sans-serif;\n  text-decoration:none;cursor:pointer;border:1px solid transparent;transition:transform .25s var(--ease-out),background .25s,box-shadow .25s;white-space:nowrap}\n.lw-btn svg{width:15px;height:15px;flex:none}\n.lw-btn:hover{transform:translateY(-1px)}\n.lw-btn:focus-visible{outline:2px solid var(--lw-copper-light);outline-offset:3px}\n.lw-btn--dark{background:var(--lw-sand);color:var(--lw-ink);border-color:#19334030;box-shadow:0 10px 30px -12px #0008}\n.lw-btn--dark:hover{background:#fff0e0}\n.lw-btn--light{background:var(--lw-rust);color:#fff5eb;box-shadow:inset 0 1px #ffffff26,0 7px 18px #54251d18}\n.lw-btn--light:hover{background:#7d3a30}\n.lw-btn--ghost{background:transparent;color:currentColor;border-color:currentColor;padding:11px 18px;font-size:14px}\n@media (max-width:860px){.lw-nav .lw-btn--ghost{padding:9px 13px;font-size:13px}}\n\n.lw-eyebrow{font:600 12px/1.4 \"DM Sans\",sans-serif;letter-spacing:.13em;text-transform:uppercase;color:var(--lw-rust)}\n.lw-accent-dark{background:linear-gradient(105deg,#f1d2c2,#e6b6ad);-webkit-background-clip:text;background-clip:text;color:transparent}\n.lw-accent-light{background:linear-gradient(105deg,#12324a,#315a73);-webkit-background-clip:text;background-clip:text;color:transparent}\n.lw-accent-rust{background:linear-gradient(105deg,#71332e,#985342);-webkit-background-clip:text;background-clip:text;color:transparent}\n\n/* Museumsschild */\n.lw-label{background:var(--lw-ivory);border:1px solid #d9cfc2;padding:14px 18px;box-shadow:0 12px 30px -20px #12324a66;color:var(--lw-ink);font-size:15px;line-height:1.45}\n.lw-label__kicker{display:block;font:500 10px/1.3 Sora,sans-serif;letter-spacing:.09em;text-transform:uppercase;color:var(--lw-label);margin-bottom:6px}\n\n/* Logo-Laufband */\n.lw-marquee{overflow:hidden;-webkit-mask:linear-gradient(90deg,transparent,#000 10%,#000 90%,transparent);mask:linear-gradient(90deg,transparent,#000 10%,#000 90%,transparent)}\n.lw-marquee__track{display:flex;align-items:center;gap:clamp(36px,5vw,72px);width:max-content;animation:lw-marquee 48s linear infinite}\n.lw-marquee img{height:26px;width:auto;opacity:.8;flex:none}\n.lw-marquee--on-dark img{filter:brightness(0) invert(1)}\n.lw-marquee--on-light img{filter:brightness(0) saturate(100%) invert(16%) sepia(26%) saturate(1200%) hue-rotate(170deg) brightness(92%);opacity:.7}\n/* Mehrfarbige Logos mit eigener Fl\u00e4che (EDEKA, itelis, OnePage) w\u00fcrden durch die Einf\u00e4rbung zu Kl\u00f6tzen:\n   auf Dunkel bleiben sie farbig, auf Hell werden sie nur ents\u00e4ttigt. */\n.lw-marquee--on-dark img:is([src*=\"kunde-edeka\"],[src*=\"kunde-itelis\"],[src*=\"kunde-onepage\"]){filter:saturate(.7);opacity:.85}\n.lw-marquee--on-light img:is([src*=\"kunde-edeka\"],[src*=\"kunde-itelis\"],[src*=\"kunde-onepage\"]){filter:grayscale(1) contrast(1.05);opacity:.6}\n@keyframes lw-marquee{to{transform:translateX(-50%)}}\n\n/* Einblenden beim Scrollen (basis.js setzt .is-in) */\n.reveal{opacity:0;transform:translateY(22px);transition:opacity .9s var(--ease-out),transform .9s var(--ease-out)}\n.reveal.is-in{opacity:1;transform:none}\n\n/* Varianten-Umschalter (nur f\u00fcr den Vergleich, geh\u00f6rt nicht zur Seite) */\n.lw-switch{position:fixed;left:12px;bottom:12px;z-index:9999;display:flex;align-items:center;gap:2px;padding:4px;border-radius:999px;\n  background:#0a202dcc;color:#f5e9dd;font:600 12px/1 \"DM Sans\",sans-serif;box-shadow:0 8px 24px -10px #000a;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}\n.lw-switch a{color:inherit;text-decoration:none;padding:8px 11px;border-radius:999px}\n.lw-switch a:hover{background:#ffffff1f}\n.lw-switch span{padding:0 6px;opacity:.75;white-space:nowrap}\n\n@media (prefers-reduced-motion:reduce){\n  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition:none!important;scroll-behavior:auto!important}\n  .reveal{opacity:1;transform:none}\n}\n\n</style>\n<style>@font-face{font-family:Anton;src:url(https://raw.githubusercontent.com/Marcofrnz/leadwriting-v1-assets/685be49c6f2634b54a2efbf78f194ce0e2c9c374/assets/v19/anton-regular.woff) format(\"woff\");font-weight:400;font-style:normal;font-display:swap}</style>\n<script>document.documentElement.classList.add('js')</script>\n<style>\n/* ===== v19 \u201eEin Kinoabend\u201c: Hero + Kinosaal =====\n   Plakat (Premiere) mit Produktionszeile, Zielgruppe, Titel, Angebot, Button + Mikrozeile, Pressezitat von Rolf, Logoband.\n   Beim Scrollen wird das Plakat zur Leinwand im Saal (Desktop, halbe Bildschirmh\u00f6he); am Handy blendet der Saal nur kurz ab.\n   Die Kopfleiste (.g-leiste) steht hier, damit sie ab Sekunde 0 fertig gestylt da ist; ihr Verhalten steuert 99-system. */\n:root{\n  --night:#060f18; --cold-deep:#315a73; --rust:#8e4338; --copper:#d29a82;\n  --cream:#f5e9dd; --cream-2:#e5dbd2; --peach:#f1d2c2; --muted:#b9aea6;\n  --anton:\"Anton\",\"Sora\",sans-serif;\n  --kopf-h:72px;\n}\nhtml{scroll-padding-top:calc(var(--kopf-h) + 12px)}\nhtml,body{background:#060f18}\nbody{color:var(--cream)}\n::selection{background:#f1d2c2;color:#12324a}\na:focus-visible{outline:2px solid var(--copper);outline-offset:4px;border-radius:4px}\n\n/* ===== Kopfleiste: ab Sekunde 0 sichtbar, im Hero durchsichtig, danach Nacht-Fl\u00e4che mit Fortschrittskugel ===== */\n.g-sprung{position:fixed;left:16px;top:-80px;z-index:1000;padding:12px 18px;border-radius:8px;background:#efddce;color:#193340;\n  font:600 15px/1.2 \"DM Sans\",sans-serif;text-decoration:none;transition:top .2s}\n.g-sprung:focus{top:12px}\n.g-leiste{position:fixed;inset:0 0 auto;z-index:900;height:var(--kopf-h);color:var(--lw-cream);transition:transform .45s var(--ease-out)}\n/* im Hero: nur ein weicher Schatten nach unten, damit Logo und Links auf hellem Licht lesbar bleiben */\n.g-leiste::before{content:\"\";position:absolute;inset:0 0 -34px;pointer-events:none;background:linear-gradient(#03070ca6,#03070c00);transition:opacity .4s}\n.g-leiste__flaeche{position:absolute;inset:0;opacity:0;transition:opacity .4s var(--ease-out);background:#060f18eb;\n  box-shadow:0 1px 0 #f5e9dd14,0 18px 40px -26px #000;-webkit-backdrop-filter:blur(12px) saturate(1.1);backdrop-filter:blur(12px) saturate(1.1)}\n.g-leiste.is-fest::before{opacity:0}\n.g-leiste.is-fest .g-leiste__flaeche{opacity:1}\n.g-leiste__innen{position:relative;height:100%;display:flex;align-items:center;gap:22px;padding:0 var(--lw-gutter)}\n.g-leiste__marke{display:block;padding:6px 0;color:inherit;flex:none}\n.g-leiste .lw-logo{width:50px;transition:width .4s var(--ease-out)}\n.g-leiste.is-fest .lw-logo{width:44px}\n/* Kapitel-Laufzeile (aktuelle Sektion), erscheint, sobald die Leiste fest ist */\n.g-leiste__kapitel{display:flex;align-items:center;gap:12px;min-width:0;margin:0;opacity:0;transition:opacity .4s;\n  font:600 11px/1.2 \"DM Sans\",sans-serif;letter-spacing:.24em;text-transform:uppercase;color:#d29a82;white-space:nowrap}\n.g-leiste__kapitel::before{content:\"\";flex:none;width:1px;height:18px;background:#f5e9dd2e}\n.g-leiste__kapitel span{overflow:hidden;text-overflow:ellipsis}\n.g-leiste__kapitel span.is-flackern{animation:g-flackern .32s steps(1,end) both}\n.g-leiste.is-fest .g-leiste__kapitel.is-gesetzt{opacity:1}\n@keyframes g-flackern{0%{opacity:.2}25%{opacity:.85}50%{opacity:.35}75%{opacity:1}}\n.g-leiste__links{display:flex;align-items:center;gap:28px;margin-left:auto;font:500 14px/1 \"DM Sans\",sans-serif}\n.g-leiste__links a:not(.lw-btn){color:#e5dbd2;text-decoration:none;padding:8px 0;text-shadow:0 1px 10px #03070c;transition:color .2s}\n.g-leiste__links a:not(.lw-btn):hover{color:#fff;text-decoration:underline;text-decoration-color:#d29a82;text-underline-offset:6px}\n.g-leiste .lw-btn{padding:11px 18px;font-size:14px;gap:10px;transition:opacity .3s,visibility 0s,transform .25s var(--ease-out)}\n.g-leiste .lw-btn svg{width:13px;height:13px}\n.g-leiste a:focus-visible{outline:2px solid #d29a82;outline-offset:4px;border-radius:4px}\n\n/* Fortschritt: feine Linie unten an der Leiste, an der Spitze rollt die Marmorkugel (Skript in 99-system) */\n.g-fortschritt{position:absolute;left:0;right:0;bottom:-1px;height:2px;pointer-events:none;transition:opacity .4s}\n.g-leiste:not(.is-fest) .g-fortschritt{opacity:0}\n.g-fortschritt__spur{position:absolute;inset:0;background:#f5e9dd12}\n.g-fortschritt__linie{position:absolute;inset:0;transform-origin:0 50%;transform:scaleX(0);\n  background:linear-gradient(90deg,#b46e63,#edc6b0);box-shadow:0 0 10px #edc6b055}\n.g-fortschritt__kugel{position:absolute;left:0;top:-7px;width:16px;height:16px;will-change:transform}\n.g-fortschritt__koerper{position:absolute;inset:0;border-radius:50%;transition:opacity .6s var(--ease-out),transform .6s var(--ease-out);filter:drop-shadow(0 2px 3px #0009)}\n.g-fortschritt__marmor{position:absolute;inset:0;width:100%;height:100%;border-radius:50%;overflow:hidden}\n.g-fortschritt__licht{position:absolute;inset:0;border-radius:50%;\n  background:radial-gradient(circle at 34% 28%,#fffdf9e6 0,#fffdf900 26%),radial-gradient(circle at 36% 30%,#0000 38%,#0a1a26a8 86%,#081520 100%);\n  box-shadow:inset 0 0 0 .5px #ffffff2e}\n.g-fortschritt.is-angekommen .g-fortschritt__koerper{opacity:0;transform:translateY(-6px) scale(.5)}\n\n/* Im Plakat nur zwei Anker (ruhiger erster Bildschirm); \u201eAblauf\u201c und \u201eFragen\u201c kommen mit der festen Leiste dazu */\n.g-leiste:not(.is-fest) .g-leiste__links a[data-weit]{display:none}\n@media (max-width:1180px){.g-leiste__links a[data-weit]{display:none}}\n@media (max-width:960px){.g-leiste__links a:not(.lw-btn){display:none}}\n@media (max-width:760px){\n  :root{--kopf-h:58px}\n  .g-leiste__innen{gap:14px}\n  .g-leiste .lw-logo{width:42px}\n  .g-leiste.is-fest .lw-logo{width:40px}\n  .g-leiste .lw-btn{padding:9px 13px;font-size:13.5px;gap:8px}\n  .g-leiste__kapitel{flex:1 1 auto;font-size:10.5px;letter-spacing:.2em}\n  /* sobald die Leiste unten da ist, wandert der Button dorthin; die Kopfleiste darf beim Lesen weggleiten.\n     Der unsichtbare Button verl\u00e4sst dabei den Fluss, damit das Kapitel die ganze Breite bekommt. */\n  html.g-unten-da .g-leiste__links{position:absolute;right:var(--lw-gutter);top:50%;transform:translateY(-50%);pointer-events:none}\n  html.g-unten-da .g-leiste .lw-btn{opacity:0;visibility:hidden;transition:opacity .25s,visibility 0s linear .25s}\n  .g-leiste.is-weg{transform:translateY(-104%)}\n  html.g-unten-da .g-leiste .g-fortschritt{display:none}\n  /* Kapitel nur, wenn der Button unten sitzt (sonst reicht der Platz neben dem Button nicht) */\n  html:not(.g-unten-da) .g-leiste__kapitel{display:none}\n}\n\n/* Korn \u00fcber allem (sehr leicht, flimmert) */\n.grain{position:absolute;inset:-60px;z-index:30;pointer-events:none;opacity:.11;mix-blend-mode:overlay;\n  background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='240' height='240'><filter id='g'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%' height='100%' filter='url(%23g)'/></svg>\");\n  animation:flimmern .9s steps(5) infinite}\n@keyframes flimmern{0%{transform:translate(0,0)}20%{transform:translate(-22px,14px)}40%{transform:translate(18px,-26px)}60%{transform:translate(-8px,30px)}80%{transform:translate(28px,6px)}100%{transform:translate(0,0)}}\n\n/* ===== Scrollb\u00fchne: Plakat wandert in den Kinosaal (halbe Bildschirmh\u00f6he Weg) ===== */\n.premiere{--H:clamp(720px,100svh,1200px);--run:min(50vh,520px);position:relative;background:#060f18}\nhtml.js .premiere{height:calc(var(--H) + var(--run))}\nhtml.js .premiere.is-flat{height:auto}\nhtml.js .premiere.is-flat .kino{position:relative}\n.premiere.is-flat .seats,.premiere.is-flat .hall,.premiere.is-flat .beam{display:none}\n.kino{--s:.6;--st:.12;position:relative;height:var(--H);overflow:hidden;isolation:isolate;background:#02060a}\nhtml.js .kino{position:sticky;top:0}\n\n/* --- Der Saal (liegt hinter dem Plakat und wird sichtbar, wenn es kleiner wird) --- */\n.hall{position:absolute;inset:0;z-index:0;opacity:0;pointer-events:none}\n.hall__room{position:absolute;inset:0;background:\n  radial-gradient(64% 62% at 50% calc((var(--st) + var(--s) / 2) * 100%),#20384c 0%,#102031 36%,#0000 70%),\n  radial-gradient(30% 40% at 0% 40%,#6a333630,#0000 70%),\n  radial-gradient(30% 40% at 100% 40%,#6a333630,#0000 70%),\n  linear-gradient(#03070b,#081420 48%,#03070b 80%,#010305)}\n.hall__room::before{content:\"\";position:absolute;inset:0;opacity:.55;\n  background:repeating-linear-gradient(90deg,#0000 0 22px,#ffffff06 22px 24px,#0000 24px 46px);\n  -webkit-mask:linear-gradient(90deg,#000 0%,#0000 26%,#0000 74%,#000 100%),linear-gradient(#0000,#000 20%,#000 70%,#0000);-webkit-mask-composite:source-in;\n  mask:linear-gradient(90deg,#000 0%,#0000 26%,#0000 74%,#000 100%) intersect,linear-gradient(#0000,#000 20%,#000 70%,#0000)}\n.hall__sconce{position:absolute;top:34%;width:6px;height:44px;border-radius:3px;background:linear-gradient(#fff3e8,#e6b6ad 60%,#8e4338);\n  box-shadow:0 0 18px 4px #f1d2c255,0 0 80px 30px #8e433833}\n.hall__sconce::after{content:\"\";position:absolute;left:50%;top:-140px;width:110px;height:330px;transform:translateX(-50%);\n  background:radial-gradient(closest-side,#e6b6ad30,#6a333618 55%,#0000);pointer-events:none}\n.hall__sconce--l{left:3.6%}\n.hall__sconce--r{right:3.6%}\n.hall__curtain{position:absolute;top:-4%;height:calc((var(--st) + var(--s)) * 100% + 9%);width:10.5%;\n  background:\n    linear-gradient(90deg,#0000 52%,#f1d2c21c 86%,#f6dccb36 100%),\n    linear-gradient(#010204 0%,#0000 24%,#0000 76%,#010204ee 100%),\n    /* drei Faltenperioden \u00fcbereinander, damit der Samt unregelm\u00e4\u00dfig f\u00e4llt */\n    repeating-linear-gradient(90deg,#0000 0 29px,#0000003a 29px 41px,#0000 41px 67px),\n    repeating-linear-gradient(90deg,#0000 0 37px,#f1d2c20c 37px 42px,#0000 42px 83px),\n    repeating-linear-gradient(90deg,#0000 0 13px,#00000048 13px 20px,#0000 20px 33px),\n    repeating-linear-gradient(90deg,#1c0a0d 0px,#3a151a 7px,#57212a 13px,#6a2a30 16px,#481b21 21px,#200c10 28px);\n  border-radius:0 0 46% 54% / 0 0 14px 10px;box-shadow:12px 0 40px -14px #000}\n.hall__curtain--l{left:calc((1 - var(--s)) * 50% - 11.4%)}\n.hall__curtain--r{right:calc((1 - var(--s)) * 50% - 11.4%);transform:scaleX(-1)}\n.hall__screen{position:absolute;left:calc((1 - var(--s)) * 50% - 9px);width:calc(var(--s) * 100% + 18px);\n  top:calc(var(--st) * 100% - 9px);height:calc(var(--s) * 100% + 18px);background:#010203;\n  box-shadow:0 0 0 1px #f5e9dd0f,0 0 140px 40px #8fb3cc14,0 60px 180px 60px #f1d2c212}\n.hall__stage{position:absolute;left:12%;right:12%;top:calc((var(--st) + var(--s)) * 100% + 14px);height:42px;\n  background:radial-gradient(50% 100% at 50% 0%,#c9d6e026,#0000 70%);filter:blur(4px)}\n\n/* --- Das Plakat (der Film) --- */\n.poster:focus,main:focus{outline:none}\n.poster{position:absolute;inset:0;z-index:2;height:var(--H);overflow:hidden;isolation:isolate;display:flex;flex-direction:column;\n  padding-top:calc(var(--kopf-h) + clamp(4px,1vh,12px));background:#050d15;transform-origin:50% 0;will-change:transform}\n/* Nachtblau mit warmem Projektorkegel und dem Premierenlicht aus v18: Rost von rechts, Kaltblau von links. Keine Sterne. */\n.poster__sky{position:absolute;inset:0;z-index:-5;background:\n  radial-gradient(52% 52% at 50% 30%,#163049 0%,#0d2232 44%,#0000 76%),\n  radial-gradient(38% 70% at 104% 48%,#7a3a3ab8 0%,#4b2a3399 34%,#0000 72%),\n  radial-gradient(36% 64% at -4% 42%,#2e5874a6 0%,#18324780 40%,#0000 74%),\n  linear-gradient(#071420,#04090f 88%)}\n\n/* Die Marmorkugel: der Stein l\u00e4uft durch dieselbe Duotone-Rechnung wie #lw-marmor (monochrom), das Licht darauf hat Farbe\n   (Rost von rechts, Kaltblau von links, wie im Premierenlicht von v18). Sie steht hinter den beiden und ist gr\u00f6\u00dfer als sie:\n   die K\u00f6pfe ragen \u00fcber ihren Rand, unten versinkt sie im eigenen Schatten. Eine Last, kein Mond. */\n.ball{position:absolute;z-index:-4;left:50%;top:calc(var(--kopf-h) + var(--H) * .56);width:min(88vh,94vw,960px);aspect-ratio:1;border-radius:50%;\n  transform:translate(-50%,-50%);animation:kugel 2.2s .1s var(--ease-out) both}\n.ball__css{position:absolute;inset:0;border-radius:50%;\n  background:radial-gradient(circle at 34% 24%,#efe4d8 0%,#cfc6bc 18%,#7e7f80 38%,#2a3741 60%,#0b1a26 80%,#091d2d 100%);\n  box-shadow:inset 14px 0 30px -18px #6f9ab8,inset -20px -6px 34px -14px #c27861}\n.ball canvas{position:absolute;inset:0;width:100%;height:100%;border-radius:50%;opacity:0;transition:opacity .6s ease-out}\n.ball.is-gl canvas,.ball.is-cpu canvas{opacity:1}\n.ball.is-cpu .ball__css{opacity:0;transition:opacity .6s ease-out}\n.ball.is-gl .ball__css{display:none}\n/* Bodenschatten: f\u00e4llt nach rechts unten (Licht von oben links); nur sichtbar, wo die Kugel ganz im Bild liegt (Variante \u201eversetzt\u201c) */\n.ball__boden{display:none;position:absolute;z-index:-1;left:-6%;right:-46%;bottom:-6%;height:17%;border-radius:50%;pointer-events:none;\n  background:radial-gradient(closest-side at 40% 50%,#010306f2 0%,#010306b8 36%,#01030650 66%,#01030600 100%);filter:blur(5px)}\n.ball__boden::after{content:\"\";position:absolute;left:22%;right:48%;top:26%;height:36%;border-radius:50%;background:#000;filter:blur(8px);opacity:.9}\n/* v18 zum Vergleich (nur \u00fcber den Pr\u00fcf-Umschalter): Kugel h\u00f6her, Gl\u00fchen dahinter */\n.ball::before{content:\"\";position:absolute;inset:-28%;border-radius:50%;z-index:-1;opacity:0;pointer-events:none;\n  background:radial-gradient(circle,#f3d9c82e 0%,#c2786130 32%,#6a33361f 50%,#0000 70%)}\n.poster[data-kugel=\"v18\"] .ball{top:41%;width:min(70vh,86vw,800px)}\n.poster[data-kugel=\"v18\"] .ball::before{opacity:1}\n/* Vorschlag aus der Design-Pr\u00fcfung (nur \u00fcber den Pr\u00fcf-Umschalter): aus der Mitte genommen, hinter Dominik, liegt auf dem Boden */\n.poster[data-kugel=\"versetzt\"] .ball{left:calc(50% + min(19vw,250px));top:calc(var(--kopf-h) + var(--H) * .27);width:min(46vh,40vw,460px)}\n.poster[data-kugel=\"versetzt\"] .ball__boden{display:block}\n@keyframes kugel{from{transform:translate(-53%,-50%)}to{transform:translate(-50%,-50%)}}\n\n/* Die beiden: nat\u00fcrliche Farbe, warmes Licht von oben links, ihr Schatten f\u00e4llt auf die Kugel (ein Raum statt Montage) */\n.stars{position:absolute;z-index:2;left:50%;top:calc(var(--H) * .16);height:min(calc(var(--H) * .97),calc(80vw / .7715));aspect-ratio:996/1291;transform:translateX(-50%);margin:0;\n  -webkit-mask:linear-gradient(#000 56%,#0008 72%,#0000 86%);mask:linear-gradient(#000 56%,#0008 72%,#0000 86%)}\n.stars img{position:relative;width:100%;height:100%;object-fit:contain;filter:brightness(.95) contrast(1.06) saturate(1.02) drop-shadow(20px 12px 30px #02060ad0)}\n/* Vorschaubild (1 KB) als Silhouette, bis das Foto da ist (langsames Mobilnetz) */\n.stars::before{content:\"\";position:absolute;inset:0;background:url(data:image/png;base64,) center/100% 100% no-repeat;filter:blur(7px) brightness(.8);transition:opacity .5s}\n.stars.is-geladen::before{opacity:0}\n.stars__light{position:absolute;inset:0;pointer-events:none;\n  -webkit-mask:url(https://onecdn.io/media/7fdb9cf7-563b-4c3d-ade1-2b529c0fad12/full) center/100% 100% no-repeat;mask:url(https://onecdn.io/media/7fdb9cf7-563b-4c3d-ade1-2b529c0fad12/full) center/100% 100% no-repeat}\n.stars__light--rim{background:linear-gradient(104deg,#ffe4d0 0%,#ffe4d000 30%);mix-blend-mode:soft-light;opacity:.6}\n.stars__light--key{background:radial-gradient(60% 30% at 44% 14%,#ffe9dc2e,#0000 70%);mix-blend-mode:screen}\n.stars__light--shade{background:linear-gradient(#0000 26%,#050d1599 62%,#050d15 84%);mix-blend-mode:multiply}\n\n/* Dunst vor den Beinen */\n.haze{position:absolute;left:0;right:0;bottom:0;height:62%;z-index:3;pointer-events:none;\n  background:\n    radial-gradient(60% 50% at 18% 100%,#315a7330,#0000 70%),\n    radial-gradient(60% 50% at 84% 100%,#6a333638,#0000 70%),\n    linear-gradient(#05101800 0%,#050d15b8 36%,#050d15f2 64%,#050d15 100%)}\n\n/* Saal dunkel, bis der Scheinwerfer z\u00fcndet (kurz, Inhalt liegt dar\u00fcber und ist sofort lesbar) */\n.dark{position:absolute;inset:0;z-index:4;background:#010306;pointer-events:none;opacity:0;animation:dunkel 1.1s .05s linear both}\n@keyframes dunkel{0%{opacity:.9}8%{opacity:.34}13%{opacity:.84}22%{opacity:.16}28%{opacity:.5}42%{opacity:0}100%{opacity:0}}\n\n/* Der warme Projektorkegel von oben (spart die beiden aus, kein grauer Schleier \u00fcber den Gesichtern) */\n.lamp{position:absolute;inset:0;z-index:5;pointer-events:none;mix-blend-mode:screen;\n  mask:linear-gradient(#000,#000),\n    url(https://onecdn.io/media/7fdb9cf7-563b-4c3d-ade1-2b529c0fad12/full) var(--mx,0) var(--my,0)/var(--mw,0) var(--mh,0) no-repeat,\n    linear-gradient(#000 50%,#0000 80%) var(--mx,0) var(--my,0)/var(--mw,0) var(--mh,0) no-repeat;\n  mask-composite:subtract,intersect;opacity:0;animation:lampe 1.1s .05s linear both}\n@keyframes lampe{0%{opacity:0}8%{opacity:.7}13%{opacity:.08}22%{opacity:.9}28%{opacity:.42}42%{opacity:1}100%{opacity:1}}\n.lamp__cone{position:absolute;left:50%;top:-9%;width:220%;height:104%;transform:translateX(-50%);filter:blur(12px);\n  background:conic-gradient(at 50% 0%,#0000 0deg 151deg,#f1d2c210 156deg,#f6e4d630 164deg,#fbeee448 172deg,#fff4ea55 180deg,#fbeee448 188deg,#f6e4d630 196deg,#f1d2c210 204deg,#0000 209deg 360deg);\n  -webkit-mask:linear-gradient(#000 0%,#000c 40%,#0000 86%);mask:linear-gradient(#000 0%,#000c 40%,#0000 86%)}\n.lamp__core{position:absolute;left:50%;top:-9%;width:220%;height:80%;transform:translateX(-50%);filter:blur(16px);\n  background:conic-gradient(at 50% 0%,#0000 0deg 167deg,#fff1e62a 174deg,#fff7f040 180deg,#fff1e62a 186deg,#0000 193deg 360deg);\n  -webkit-mask:linear-gradient(#000 0%,#0000 92%);mask:linear-gradient(#000 0%,#0000 92%)}\n.lamp__rays{position:absolute;left:50%;top:-9%;width:220%;height:96%;transform:translateX(-50%);opacity:.8;\n  background:repeating-conic-gradient(at 50% 0%,#0000 0deg,#fff3e610 .5deg,#0000 1.3deg,#0000 2.7deg,#fff3e60a 3.2deg,#0000 4.1deg);\n  -webkit-mask:conic-gradient(at 50% 0%,#0000 0deg 156deg,#000 166deg 194deg,#0000 204deg 360deg),linear-gradient(#000 10%,#0000 80%);-webkit-mask-composite:source-in;\n  mask:conic-gradient(at 50% 0%,#0000 0deg 156deg,#000 166deg 194deg,#0000 204deg 360deg) intersect,linear-gradient(#000 10%,#0000 80%);\n  animation:strahlen 9s ease-in-out infinite alternate}\n@keyframes strahlen{from{transform:translateX(-50%) rotate(-.6deg)}to{transform:translateX(-50%) rotate(.6deg)}}\n.lamp__spot{position:absolute;left:50%;top:-70px;width:min(460px,70vw);height:150px;transform:translateX(-50%);\n  background:radial-gradient(closest-side,#fff8f2 0%,#fbe9dccc 22%,#f1d2c240 55%,#0000);filter:blur(4px)}\n/* Lichtpf\u00fctze nur \u00fcber den Gesichtern; \u00fcber dem Kugelrand gedimmt, damit oben kein heller Saum entsteht */\n.lamp__pool{position:absolute;left:50%;top:calc(var(--H) * .2);width:min(760px,90vw);height:calc(var(--H) * .5);transform:translateX(-50%);\n  background:radial-gradient(50% 50% at 50% 30%,#f6e4d60e,#0000 70%)}\n\n/* Einlauf der Textteile: kurz, alles steht nach weniger als 1,5 s */\n.in{animation:auf .8s var(--ease-out) both;animation-delay:var(--d,.3s)}\n@keyframes auf{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n\n/* Billing wie auf dem Premiere-Plakat (v18): die Namen gro\u00df in der Plakatschrift \u00fcber den K\u00f6pfen, darunter leise, wer sie sind */\n.credits{position:relative;z-index:8;margin:0;padding:0 var(--lw-gutter);text-align:center;color:var(--cream)}\n.credits__namen{display:flex;justify-content:center;gap:clamp(48px,13vw,250px);\n  font:400 clamp(17px,1.6vw,25px)/1 var(--anton);letter-spacing:.22em;text-transform:uppercase;color:#f5e9ddec;text-shadow:0 2px 16px #000c}\n.credits__namen span{position:relative;white-space:nowrap;margin-right:-.22em}\n/* weicher dunkler Grund je Name, damit er nie auf hellem Licht steht */\n.credits__namen span::before{content:\"\";position:absolute;z-index:-1;inset:-16px -34px;pointer-events:none;\n  background:radial-gradient(closest-side,#050d15e6 0%,#050d15b0 48%,#050d1500 100%)}\n.credits__zusatz{display:block;margin-top:clamp(7px,1vh,10px);font:500 clamp(13.5px,1vw,15px)/1.2 Sora,sans-serif;letter-spacing:-.01em;color:#e5dbd2;\n  text-shadow:0 1px 3px #03070c,0 2px 14px #03070c}\n\n/* Titelblock: Zielgruppe \u2192 Titel \u2192 Angebot \u2192 Handlung (Button | Pressezitat) */\n.bill{position:relative;z-index:10;margin-top:auto;text-align:center;padding:0 var(--lw-gutter)}\n.bill::before{content:\"\";position:absolute;z-index:-1;left:50%;top:-50px;width:min(1500px,120%);height:calc(100% + 40px);transform:translateX(-50%);pointer-events:none;\n  background:radial-gradient(50% 46% at 50% 44%,#050d15c9 0%,#050d1578 48%,#050d1500 100%)}\n.kicker{display:inline-flex;align-items:center;gap:14px;margin:0 0 clamp(8px,1.3vh,14px);font:500 clamp(17px,1.34vw,20px)/1.3 Sora,sans-serif;letter-spacing:-.012em;color:var(--cream);\n  text-shadow:0 1px 14px #000,0 0 2px #000}\n.kicker::before,.kicker::after{content:\"\";flex:none;width:clamp(20px,2.2vw,34px);height:1px;background:linear-gradient(90deg,#d29a8200,#d29a82b0)}\n.kicker::after{transform:scaleX(-1)}\n/* Der gro\u00dfe Titel ist das Nutzenversprechen. Schriftgr\u00f6\u00dfe setzt das Skript so, dass die l\u00e4ngste Zeile passt. */\n/* Zeilenh\u00f6he 1,0: Die Umlautpunkte (\u201eF\u00dcR\u201c) sto\u00dfen nicht mehr in die Zeile dar\u00fcber; die Gr\u00f6\u00dfe ist daf\u00fcr um 3 % kleiner */\n.title{display:block;margin:0;font:400 var(--tfs,clamp(43px,min(5.45vw,8.7vh),107px))/1 var(--anton);letter-spacing:.012em;text-transform:uppercase;\n  filter:drop-shadow(0 6px 26px #000c);padding:0 .02em;animation:zoom 1.6s .1s var(--ease-out) both}\n.title .l{display:block;width:max-content;max-width:100%;margin:0 auto;text-wrap:balance}\n.title .w{display:inline-block;white-space:nowrap;padding-top:.16em;margin-top:-.16em;background:linear-gradient(180deg,#fbf2e9 18%,#f5e1d2 52%,#efc6b6 100%);-webkit-background-clip:text;background-clip:text;color:transparent;\n  animation:fokus .9s var(--ease-out) both;animation-delay:calc(.12s + var(--i) * .045s)}\n.title.is-measuring .l{max-width:none}\n@keyframes fokus{0%{opacity:0;filter:blur(16px);transform:scale(1.1)}45%{opacity:1}100%{opacity:1;filter:blur(0);transform:none}}\n@keyframes zoom{from{transform:scale(1.035)}to{transform:none}}\n.offer{max-width:min(46em,92vw);margin:clamp(10px,1.7vh,18px) auto 0;font:500 clamp(17px,min(1.32vw,2.2vh),20px)/1.45 Sora,sans-serif;letter-spacing:-.02em;color:var(--cream);text-wrap:balance;\n  text-shadow:0 1px 18px #050d15}\n.offer em{font-style:normal;color:var(--peach)}\n\n/* Handlung: links der Button mit Mikrozeile, rechts das Pressezitat. Der Strich steht genau auf der Mittelachse. */\n.handlung{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:0 clamp(26px,2.6vw,44px);margin-top:clamp(16px,2.5vh,28px);text-align:left}\n.handlung__cta{position:relative;justify-self:end;display:flex;flex-direction:column;align-items:center}\n/* warmes Licht hinter dem Button (die Ticket-Kerben-Maske schneidet Schatten am Button selbst ab) */\n.handlung__cta::before{content:\"\";position:absolute;z-index:-1;left:50%;top:28px;width:360px;height:130px;transform:translate(-50%,-50%);pointer-events:none;\n  background:radial-gradient(closest-side,#f1d2c230,#f1d2c200)}\n.handlung__cta .lw-btn{padding:17px 26px;font-size:16px}\n.handlung__cta .g-mikro{margin-top:11px;text-shadow:0 1px 12px #050d15}\n.handlung__strich{align-self:stretch;width:1px;background:linear-gradient(#f5e9dd00,#f5e9dd3d 22%,#f5e9dd3d 78%,#f5e9dd00)}\n.beleg{justify-self:start;display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:0 16px;margin:0;max-width:560px;text-shadow:0 1px 12px #050d15}\n/* Rolfs Portr\u00e4t ist zugleich der Startknopf f\u00fcr seinen Kundenfilm */\n.beleg__bild{position:relative;display:block;width:62px;height:62px;border-radius:50%;\n  background:url(https://onecdn.io/media/ead78ee5-6ef0-4eaf-b896-e4716061df25/full) 50% 6%/530% auto no-repeat,url(data:image/jpeg;base64,) 50% 6%/530% auto no-repeat,#2a2622;\n  box-shadow:0 0 0 1px #f5e9dd66,0 0 0 4px #050d15,0 0 0 5px #f1d2c238,0 12px 24px -10px #000;transition:box-shadow .25s var(--ease-out)}\na.beleg__bild:hover,a.beleg__bild:focus-visible{box-shadow:0 0 0 1px #f1d2c2,0 0 0 4px #050d15,0 0 0 5px #f1d2c27a,0 12px 24px -10px #000}\na.beleg__bild:focus-visible{outline:2px solid var(--copper);outline-offset:6px;border-radius:50%}\n.beleg__play{position:absolute;right:-5px;bottom:-3px;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;\n  background:#f5e9dd;color:#12324a;box-shadow:0 0 0 3px #050d15,0 4px 10px -4px #000}\n.beleg__play svg{width:10px;height:10px;margin-left:2px}\n.beleg__text{min-width:0}\n.beleg__zitat{margin:0;font:500 18px/1.3 Sora,sans-serif;letter-spacing:-.02em;color:var(--cream)}\n.beleg__zitat p{margin:0}\n.beleg__zahlen{margin:5px 0 0;font:600 14.5px/1.4 \"DM Sans\",sans-serif;color:var(--peach)}\n.beleg__zahlen span{white-space:nowrap}\n.beleg__kurz{display:none}\n.beleg__wer{margin:3px 0 0;display:flex;flex-wrap:wrap;align-items:center;gap:2px 14px;font:500 14px/1.4 \"DM Sans\",sans-serif;color:var(--cream-2)}\n/* Tippfl\u00e4che mindestens 44 px hoch, ohne das Layout zu verschieben */\n.beleg__film{display:inline-flex;align-items:center;gap:7px;padding:12px 0;margin:-12px 0;color:var(--cream);text-decoration:underline;text-decoration-color:#f1d2c266;text-underline-offset:4px;font-weight:600}\n.beleg__film:hover{text-decoration-color:var(--peach)}\n.beleg__film svg{width:16px;height:16px;flex:none}\n\n/* Fu\u00df: Kundenlogos */\n.foot{position:relative;z-index:10;text-align:center;padding:0 var(--lw-gutter) clamp(12px,2vh,22px)}\n.studios{position:relative;max-width:min(1180px,96vw);margin:clamp(28px,4vh,44px) auto 0}\n.studios__line{display:flex;align-items:center;justify-content:center;gap:14px;margin:0;font:500 13px/1.3 \"DM Sans\",sans-serif;letter-spacing:.16em;text-transform:uppercase;color:#cbbfb6}\n.studios__line::before,.studios__line::after{content:\"\";flex:1;min-width:24px;height:1px;background:linear-gradient(90deg,#0000,#d29a8259)}\n.studios__line::after{background:linear-gradient(90deg,#d29a8259,#0000)}\n/* offene Bewertungszeile: hier leise als Rahmen, nicht als zweite Sand-Fl\u00e4che neben dem Button */\n.studios .g-platzhalter{flex:none;background:none;color:#efddce;border:1px dashed #efddce8c;padding:2px 8px;font:600 12px/1.3 \"DM Sans\",sans-serif;letter-spacing:0;text-transform:none}\n.studios__band{position:relative;margin-top:12px}\n.studios .lw-marquee{padding:3px 0}\n.studios .lw-marquee:hover .lw-marquee__track,.studios:focus-within .lw-marquee__track,.studios.is-pause .lw-marquee__track{animation-play-state:paused}\n/* Start so verschoben, dass freenet (RolfShop24) und EDEKA Haupenthal beim Laden mitten im Band stehen, nicht in der Randblende */\n.studios .lw-marquee__track{--lh:clamp(24px,calc(var(--H) * .031),30px);gap:clamp(40px,4.4vw,72px);animation-duration:90s;animation-delay:calc(var(--start,0) * -90s)}\n.studios .lw-marquee img{height:calc(var(--lh) * var(--k,1));opacity:.86;filter:url(#creme)}\n.studios .lw-marquee--on-dark img[src*=\"kunde-edeka\"]{filter:url(#creme-tafel-edeka);opacity:.92}\n.studios .lw-marquee--on-dark img[src*=\"kunde-itelis\"]{filter:url(#creme-tafel-itelis);opacity:.9}\n.studios .lw-marquee--on-dark img[src*=\"kunde-onepage\"]{filter:url(#creme-hart)}\n/* Bildmarken ohne Wort bekommen ihren Namen dazu, sonst erkennt sie niemand */\n.studios .marke{display:inline-flex;align-items:center;gap:10px;flex:none;font:600 15px/1 Sora,sans-serif;letter-spacing:-.025em;color:#f5e9dddb;white-space:nowrap}\n.studios .marke small{display:block;margin-top:4px;font:500 12px/1.1 \"DM Sans\",sans-serif;letter-spacing:.01em;color:#cbbfb6}\n/* EDEKA: nur das Signet (der Schriftzug \u201eHaupenthal\u201c im Bild ist zu klein), der Name steht als Wort daneben */\n.studios .marke__signet{display:block;flex:none;height:calc(var(--lh) * 1.22);overflow:hidden}\n.studios .marke__signet img{display:block;height:calc(var(--lh) * 1.22 / .8)}\n/* Logoband anhalten (Tastatur und Touch), WCAG 2.2.2 */\n.studios__pause{position:absolute;right:-6px;top:50%;transform:translateY(-50%);z-index:2;width:30px;height:30px;padding:0;border:0;border-radius:50%;cursor:pointer;\n  display:grid;place-items:center;background:#0a1a28cc;color:#e5dbd2;opacity:.62;transition:opacity .2s,background .2s}\n.studios__pause:hover,.studios__pause:focus-visible{opacity:1;background:#12324a}\n.studios__pause:focus-visible{outline:2px solid var(--copper);outline-offset:2px}\n.studios__pause svg{width:12px;height:12px}\n.studios__pause .ic-play,.studios.is-pause .studios__pause .ic-pause{display:none}\n.studios.is-pause .studios__pause .ic-play{display:block}\n.poster__proj{position:absolute;inset:0;z-index:12;pointer-events:none;opacity:0;\n  background:radial-gradient(120% 95% at 50% 45%,#0000 52%,#00000080 100%),linear-gradient(#f5e9dd0a,#0000 30%)}\n.poster__dunkel{position:absolute;inset:0;z-index:13;pointer-events:none;opacity:0;background:#03070c}\n\n/* Pr\u00fcf-Umschalter (Headline, Kugel) und die Varianten-Leiste aus basis.js geh\u00f6ren nicht zur Seite:\n   sichtbar nur mit ?pruefen oder lokal ohne ?vorschau (html.g-pruefen), Besucher der echten Seite sehen sie nie */\nhtml:not(.g-pruefen) .lw-switch{display:none!important}\n.hl-switch{position:fixed;right:12px;bottom:12px;z-index:9999;display:flex;flex-wrap:wrap;justify-content:flex-end;align-items:center;gap:2px;padding:4px;border-radius:22px;max-width:calc(100vw - 24px);\n  background:#0a202dcc;color:#f5e9dd;font:600 12px/1 \"DM Sans\",sans-serif;box-shadow:0 8px 24px -10px #000a;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);transition:bottom .4s var(--ease-out)}\n.hl-switch__gruppe{display:flex;align-items:center;gap:2px}\n.hl-switch__gruppe + .hl-switch__gruppe{border-left:1px solid #f5e9dd2e;margin-left:4px;padding-left:4px}\n.hl-switch span{padding:0 6px 0 8px;opacity:.75;white-space:nowrap}\n.hl-switch button{appearance:none;border:0;background:none;color:inherit;font:inherit;cursor:pointer;padding:8px 11px;border-radius:999px}\n.hl-switch button:hover{background:#ffffff1f}\n.hl-switch button[aria-pressed=\"true\"]{background:#f5e9dd;color:#0a202d}\n.hl-switch button:focus-visible{outline:2px solid var(--copper);outline-offset:1px}\n/* am Handy klein in die rechte obere Ecke unter die Kopfleiste, damit Rolfs Beleg im ersten Bildschirm frei bleibt */\n.hl-switch__auf{display:none}\n@media (max-width:760px){\n  /* am Handy eingeklappt: nur \u201ePr\u00fcfen\u201c oben rechts, Tippen klappt Headline und Kugel auf; die Varianten-Leiste erst nach dem Plakat */\n  .hl-switch,:root.g-unten-da .hl-switch{top:calc(var(--kopf-h) + 4px);bottom:auto;right:6px;font-size:11px;padding:3px;opacity:.86}\n  .hl-switch span{display:none}.hl-switch button{padding:6px 8px}\n  .hl-switch__auf{display:block}\n  .hl-switch:not(.is-offen) .hl-switch__gruppe{display:none}\n  html.g-pruefen:not(.g-unten-da) .lw-switch{display:none}\n}\n\n/* --- Projektorstrahl, Staub, Sitzreihen --- */\n.beam{position:absolute;inset:0;z-index:3;pointer-events:none;mix-blend-mode:screen;opacity:0;filter:blur(16px)}\n.beam__shape{position:absolute;inset:0;\n  background:\n    radial-gradient(26% 20% at 50% 0%,#fff3e870,#0000 70%),\n    repeating-conic-gradient(at 50% -14%,#0000 0deg,#fff1e40e 1deg,#0000 2.2deg,#0000 3.6deg),\n    linear-gradient(#f6e4d640 0%,#f6e4d61c calc(var(--st) * 100%),#f6e4d60c 60%,#0000 calc((var(--st) + var(--s)) * 100%))}\n.dust{position:absolute;inset:0;width:100%;height:100%;z-index:4;pointer-events:none;opacity:0;animation:staub 1.2s .5s ease-out both}\n@keyframes staub{to{opacity:1}}\n.seats{position:absolute;inset:0;z-index:6;pointer-events:none}\n.seats__fade{position:absolute;left:0;right:0;bottom:0;height:10%;z-index:5;opacity:0;background:linear-gradient(#060f1800,#060f18d9 70%,#060f18)}\n.seat-row{position:absolute;left:0;right:0;bottom:0;opacity:0;will-change:transform}\n.seat-row svg{position:absolute;left:0;top:0;width:100%;height:100%;overflow:visible;z-index:1}\n/* vorderste Reihe leicht unscharf: Tiefensch\u00e4rfe wie durch ein Objektiv */\n.seat-row--a svg{filter:blur(1.8px)}\n/* Der reservierte Platz: leer, ein warmes Licht liegt darauf, an der Lehne h\u00e4ngt die Platzkarte (dieselbe Nummer wie auf der Eintrittskarte) */\n.saal-licht{position:absolute;z-index:2;pointer-events:none;opacity:0;border-radius:50%;\n  background:radial-gradient(closest-side,#ffe2c838,#f1d2c214 50%,#f1d2c200);mix-blend-mode:screen}\n.saal-karte{position:absolute;z-index:3;margin:0;opacity:0;display:grid;justify-items:center;gap:3px;padding:11px 15px 10px;min-width:140px;\n  background:linear-gradient(#fbf6ef,#efe6da);border:1px solid #d9cfc2;border-radius:3px;color:#193340;text-align:center;\n  box-shadow:inset 0 0 0 3px #fbf6ef,inset 0 0 0 4px #e3d7c7,0 14px 22px -12px #000,0 0 34px -8px #f1d2c240}\n.saal-karte::before{content:\"\";position:absolute;left:50%;top:-6px;width:26px;height:7px;transform:translateX(-50%);border-radius:2px 2px 0 0;\n  background:linear-gradient(#e0cdb2,#a8865f)}\n.saal-karte__ort{font:600 9.5px/1.2 \"DM Sans\",sans-serif;letter-spacing:.2em;text-transform:uppercase;color:#6c4336;white-space:nowrap}\n.saal-karte__res{font:400 19px/1 var(--anton);letter-spacing:.09em;text-transform:uppercase;color:#12324a}\n.saal-karte__fuer{font:500 13px/1.1 Sora,sans-serif;letter-spacing:-.01em;color:#263e4e}\n\n/* ===== Tablet ===== */\n@media (max-width:1000px){\n  .handlung{grid-template-columns:1fr;justify-items:center;gap:0}\n  .handlung__cta{justify-self:center}\n  .handlung__strich{display:none}\n  .beleg{justify-self:center;margin-top:18px}\n}\n\n/* ===== Handy ===== */\n@media (max-width:760px){\n  .premiere{--H:clamp(600px,100svh,1000px);--run:min(40vh,340px)}\n  .kino{--s:1;--st:0}\n  .poster{padding-top:calc(var(--kopf-h) + 4px)}\n  /* Namen in einer Zeile ohne \u201eund\u201c, darunter klein, wer sie sind */\n  .credits{padding:0 12px}\n  .credits__namen{gap:0 clamp(18px,6vw,30px);font-size:clamp(14px,4vw,16px);letter-spacing:.16em}\n  .credits__namen span{margin-right:-.16em}\n  .credits__namen span::before{inset:-10px -18px}\n  .credits__zusatz{margin-top:5px;font-size:12.5px}\n  .poster__sky{background:\n    radial-gradient(70% 280px at 50% 220px,#183450 0%,#0e2333 45%,#0000 78%),\n    radial-gradient(62% 300px at 108% 250px,#7a3a3ab0 0%,#4b2a3380 36%,#0000 72%),\n    radial-gradient(62% 300px at -8% 230px,#2e5874a6 0%,#18324780 40%,#0000 74%),\n    linear-gradient(#071420,#050d15 560px)}\n  /* B\u00fchne wieder in v18-Gr\u00f6\u00dfe: die beiden gro\u00df, die Kugel dahinter sichtbar; der Titelblock liegt unten \u00fcber dem Dunst */\n  .stage-m{position:relative;flex:0 0 auto;height:clamp(176px,calc(var(--H) - 588px),330px);margin-top:4px}\n  .ball{top:calc(min(86vw,380px) * .62);width:min(92vw,400px)}\n  .poster[data-kugel=\"v18\"] .ball{top:min(46%,190px);width:min(86vw,370px)}\n  .poster[data-kugel=\"versetzt\"] .ball{left:76%;top:calc(min(86vw,380px) * .3);width:min(52vw,220px)}\n  .stars{top:2px;height:auto;width:min(86vw,380px);-webkit-mask:linear-gradient(#000 38%,#0009 50%,#0000 62%);mask:linear-gradient(#000 38%,#0009 50%,#0000 62%)}\n  .stars img{filter:brightness(.95) contrast(1.06) saturate(1.02) drop-shadow(12px 8px 18px #02060ad0)}\n  .haze{height:62%;background:radial-gradient(100% 100% at 50% 100%,#050d15f2 40%,#050d1500 80%)}\n  .haze::after{content:\"\";position:absolute;left:0;right:0;top:100%;height:100%;background:radial-gradient(100% 100% at 50% 0%,#050d15f2 40%,#050d1500 80%)}\n  .lamp__cone,.lamp__core,.lamp__rays{top:-6%}\n  .lamp__pool{top:80px;height:300px}\n  .bill{margin-top:-30px}\n  .kicker{display:block;font-size:16.5px;margin:0 auto 8px;max-width:22em;text-wrap:balance}\n  .kicker::before,.kicker::after{display:none}\n  .title{font-size:var(--tfs,clamp(32px,9.4vw,40px));line-height:1.04}\n  .title .l{width:auto}\n  .offer{font-size:16.5px;line-height:1.42;max-width:36ch;margin-top:10px}\n  .handlung{margin-top:16px}\n  .handlung__cta .lw-btn{padding:15px 24px;font-size:16px}\n  .handlung__cta .g-mikro{margin-top:9px}\n  /* Beleg am Handy in zwei Zeilen: Portr\u00e4t (startet den Film) \u00b7 Zitat \u00b7 \u201eRolf \u00b7 +30 Vertr\u00e4ge im Monat\u201c */\n  .beleg{margin-top:16px;max-width:min(100%,370px);gap:0 14px}\n  .beleg__bild{width:52px;height:52px;box-shadow:0 0 0 1px #f5e9dd66,0 0 0 3px #050d15,0 0 0 4px #f1d2c238,0 10px 20px -10px #000}\n  .beleg__zitat{font-size:16.5px}\n  .beleg__zahlen{display:none}\n  .beleg__kurz{display:block;margin:3px 0 0;font:600 14.5px/1.35 \"DM Sans\",sans-serif;color:var(--peach)}\n  .beleg__kurz span{color:var(--cream-2);font-weight:500}\n  .beleg__wer{display:none}\n  .foot{display:flex;flex-direction:column;align-items:center;padding-left:0;padding-right:0}\n  .studios{width:100%;max-width:none;margin-top:26px}\n  .studios__line{flex-wrap:wrap;font-size:13px;letter-spacing:.1em;gap:6px 10px;padding:0 var(--lw-gutter)}\n  .studios__line::before,.studios__line::after{display:none}\n  .studios__band{margin-top:10px}\n  .studios .lw-marquee__track{--lh:20px;gap:34px;animation-duration:70s;animation-delay:calc(var(--start,0) * -70s)}\n  .studios .marke{font-size:13px;gap:8px}\n  .studios .marke small{font-size:11px}\n  .studios__pause{right:4px}\n  .saal-karte{min-width:118px;padding:9px 12px 8px;gap:2px}\n  .saal-karte::before{width:20px;height:5px;top:-5px}\n  .saal-karte__ort{font-size:8.5px;letter-spacing:.16em}\n  .saal-karte__res{font-size:17px}\n  .saal-karte__fuer{font-size:11.5px}\n}\n@media (max-width:370px){\n  .credits__namen{letter-spacing:.12em;gap:0 14px}\n  .beleg__zitat{font-size:16px}\n}\n/* kleine Handys (375 \u00d7 667, iPhone SE/8): B\u00fchne und Abst\u00e4nde knapper, damit Rolfs Beleg samt Zahl in den ersten Bildschirm passt */\n@media (max-width:760px) and (max-height:720px){\n  .credits__zusatz{margin-top:3px}\n  .stage-m{height:clamp(150px,calc(var(--H) - 520px),176px);margin-top:2px}\n  .stars{width:min(74vw,320px)}\n  .ball{top:calc(min(74vw,320px) * .62);width:min(80vw,340px)}\n  .bill{margin-top:-50px}\n  .kicker{margin-bottom:6px}\n  .offer{margin-top:8px}\n  .handlung{margin-top:10px}\n  .handlung__cta .lw-btn{padding:13px 22px}\n  .handlung__cta .g-mikro{margin-top:7px}\n  .beleg{margin-top:8px}\n}\n@media (min-width:761px){.stage-m{display:contents}}\n\n@media (prefers-reduced-motion:reduce){\n  .grain,.lamp__rays{animation:none}\n  /* Logoband steht, mit freenet und EDEKA im Bild */\n  .studios .lw-marquee__track{animation:none;transform:translateX(calc(var(--start,0) * -50%))}\n  .studios__pause{display:none}\n  .in,.title,.title .w,.dark,.lamp,.dust,.ball{animation-delay:0s!important}\n  .title .w{filter:none}\n}\n</style>");
